    assert_eq!(initials("ada lovelace"), "AL");
    assert_eq!(initials("\u{e9}mile zola"), "\u{c9}Z");
    assert_eq!(initials("  \u{f1}and\u{fa}   p\u{e9}rez  "), "\u{d1}P");
    assert_eq!(initials("\u{65e5}\u{672c} \u{8a9e}"), "\u{65e5}\u{8a9e}");
    assert_eq!(initials(""), "");
    assert_eq!(initials("   "), "");
}

#[test]
