    chosen = [m for m, r in ranks.items() if r <= n]
    return sorted(chosen, key=lambda m: (ranks[m], m))


def median(values):
    if not values:
        raise ValueError("median of nothing")
    ordered = sorted(values)
    mid = len(ordered) // 2
    if len(ordered) % 2:
        return ordered[mid]
    return (ordered[mid - 1] + ordered[mid]) / 2

