#!/usr/bin/env bash
# backupctl: snapshots of a directory as tar files with a checksum manifest.
set -u
root=$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)
. "$root/lib/common.sh"
. "$root/lib/create.sh"
. "$root/lib/list.sh"
. "$root/lib/prune.sh"
. "$root/lib/verify.sh"
. "$root/lib/restore.sh"

main() {
  local cmd=${1:-}
  [ $# -gt 0 ] && shift
  case $cmd in
    create) cmd_create "$@" ;;
    list) cmd_list "$@" ;;
    prune) cmd_prune "$@" ;;
    verify) cmd_verify "$@" ;;
    restore) cmd_restore "$@" ;;
    help | -h | --help) usage; return 0 ;;
    *) usage; return 2 ;;
  esac
}

main "$@"

